-- The Sales area, first tables (docs/plan.md §1.164 "The Sales area, first tables"; ARCHITECTURE
-- §12.0): the Sales pack's `crm_record_key` (each synced CRM record's normalised keys, its match
-- text with a trigram index, and that text's embedding), `crm_match` (each input row's decision:
-- by key, alias, text, meaning, the model or a person, with its score, agent version and sources)
-- and `crm_alias` (a person's answer, so the same row matches by itself next time). New tables
-- only, so the previous Worker keeps working. Generated by drizzle-kit from
-- packs/sales/src/schema.ts; the grants, row-level security, history trigger and pack comments at
-- the end are hand-written. pg_trgm and vector come from 0000. Named 0072 after 0071.
CREATE TABLE "crm_alias" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"connection_id" uuid NOT NULL,
	"module" text NOT NULL,
	"key_hash" text NOT NULL,
	"keys" jsonb NOT NULL,
	"record_key_id" uuid NOT NULL,
	"external_id" text NOT NULL,
	"match_id" uuid NOT NULL,
	"created_by_user_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "crm_alias_keys_key" UNIQUE("tenant_id","connection_id","module","key_hash"),
	CONSTRAINT "crm_alias_key_hash_check" CHECK ("crm_alias"."key_hash" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "crm_alias_keys_check" CHECK (jsonb_typeof("crm_alias"."keys") = 'object' and "crm_alias"."keys" <> '{}')
);
