	"run_id" uuid,
	"step" text,
	"row_index" integer NOT NULL,
	"keys" jsonb NOT NULL,
	"decision" text NOT NULL,
	"method" text NOT NULL,
	"record_key_id" uuid,
	"connection_id" uuid,
	"module" text,
	"external_id" text,
	"score" numeric(4, 3) NOT NULL,
	"candidates" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"sources" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"agent_version_id" uuid,
	"decided_by_user_id" uuid,
	"decided_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "crm_match_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "crm_match_decision_check" CHECK ("crm_match"."decision" in ('matched', 'none', 'unsure')),
	CONSTRAINT "crm_match_method_check" CHECK ("crm_match"."method" in ('key', 'alias', 'text', 'meaning', 'model', 'human')),
	CONSTRAINT "crm_match_row_index_check" CHECK ("crm_match"."row_index" >= 0),
	CONSTRAINT "crm_match_score_check" CHECK ("crm_match"."score" between 0 and 1),
	CONSTRAINT "crm_match_record_check" CHECK (("crm_match"."decision" = 'matched') = ("crm_match"."record_key_id" is not null)
        and num_nonnulls("crm_match"."record_key_id", "crm_match"."connection_id", "crm_match"."module", "crm_match"."external_id") in (0, 4)),
	CONSTRAINT "crm_match_decided_by_check" CHECK (num_nonnulls("crm_match"."agent_version_id", "crm_match"."decided_by_user_id") = 1
        and ("crm_match"."method" = 'human') = ("crm_match"."decided_by_user_id" is not null)),
	CONSTRAINT "crm_match_step_check" CHECK ("crm_match"."step" is null or length("crm_match"."step") between 1 and 200)
);
