-- Keys are rebuilt when a newer version of their record syncs (an update), never deleted; an alias
-- is replaced by a person's later answer for the same values (an update), never deleted.
GRANT SELECT, INSERT, UPDATE ON crm_record_key, crm_alias TO cs_runtime;
--> statement-breakpoint
-- Matching decisions are a log: a person's decision is a new row after the agent's.
GRANT SELECT, INSERT ON crm_match TO cs_runtime;
--> statement-breakpoint
CREATE TRIGGER crm_match_immutable BEFORE UPDATE OR DELETE ON crm_match
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except();
--> statement-breakpoint
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['crm_record_key', 'crm_match', 'crm_alias'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()))', t);
    EXECUTE format('COMMENT ON TABLE %I IS %L', t, 'pack:sales');
  END LOOP;
END
$$;
